<div class="d-flex flex-wrap gap-2 justify-content-between mb-4"><h1 class="h3">Shipments</h1><div><a class="btn btn-outline-success" href="export-shipments.php">Export CSV</a> <a class="btn btn-primary" href="shipment-add.php">+ Add Shipment</a></div></div><form class="card p-3 mb-3"><div class="row g-2"><div class="col-lg-4"><input class="form-control" name="q" value="<?=e($q)?>" placeholder="Search JTR number"></div><div class="col-lg-3"><select class="form-select" name="customer_id"><option value="">All customers</option><?php foreach($customers as $c):?><option value="<?=$c['id']?>" <?=$cid===$c['id']?'selected':''?>><?=e($c['name'].' ('.$c['code'].')')?></option><?php endforeach;?></select></div><div class="col-lg-3"><select class="form-select" name="status"><option value="">All statuses</option><?php foreach(status_labels() as $k=>$v):?><option value="<?=e($k)?>" <?=$status===$k?'selected':''?>><?=e($v)?></option><?php endforeach;?></select></div><div class="col-lg-2"><button class="btn btn-outline-primary w-100">Filter</button></div></div></form><div class="card table-card"><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Brand / JTR</th><th>Customer</th><th>Weight / Price</th><th>Date</th><th style="min-width:200px">Status</th><th>Actions</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><small class="text-muted d-block"><?=e($r['brand_name']?:'-')?></small><strong><?=e($r['jtr_number'])?></strong></td><td><?=e($r['customer_name'])?></td><td><?=e($r['weight'])?> KG<br><small><?=$r['price']!==null?'$ '.e(number_format((float)$r['price'],2)):'-'?></small></td><td><?=e($r['shipment_date'])?></td><td><form method="post"><?=csrf_field()?><input type="hidden" name="status_id" value="<?=$r['id']?>"><select class="form-select form-select-sm" name="status" onchange="this.form.submit()"><?php foreach(status_labels() as $k=>$v):?><option value="<?=e($k)?>" <?=$r['status']===$k?'selected':''?>><?=e($v)?></option><?php endforeach;?></select></form></td><td class="text-nowrap"><a class="btn btn-sm btn-outline-primary" href="shipment-receipt.php?id=<?=$r['id']?>">Print</a> <a class="btn btn-sm btn-outline-secondary" href="shipment-edit.php?id=<?=$r['id']?>">Edit</a> <form method="post" class="d-inline" onsubmit="return confirm('Delete this shipment?')"><?=csrf_field()?><input type="hidden" name="delete_id" value="<?=$r['id']?>"><button class="btn btn-sm btn-outline-danger">Delete</button></form></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="6" class="text-center text-muted py-4">No shipments found.</td></tr><?php endif;?></tbody></table></div></div><?php require __DIR__.'/../includes/admin-footer.php';
